import java.util.*;
import java.io.*;

public class Main {
    static final int B = 1000000;
    static final int mod1 = 998244353;
    static final int mod2 = 1000000007;
    static long n, counter;
    static List<Integer>[] v = new ArrayList[10];
    static long[] sum = new long[10];
    static long answer = 0;
    static long total = 0;

    static {
        for (int i = 0; i < 10; i++) {
            v[i] = new ArrayList<>();
        }
    }

    static int calc_mod(long x) {
        long res = (x % mod1 + mod1) % mod1;
        return (int) res;
    }

    static void generate_sequences(int depth, long number) {
        counter++;
        v[depth].add(calc_mod(counter - number));
        if (depth == 6) return;
        for (int digit = 0; digit <= 9; digit++) {
            generate_sequences(depth + 1, number * 10 + digit);
        }
    }

    static void process_numbers(int depth, long number) {
        if (number > n) return;
        if (depth >= 1) {
            if (number * B > n / 10 && (number + 1) * B - 1 <= n) {
                int multiplier = 1;
                for (int i = 0; i <= 6; i++, multiplier *= 10) {
                    int w = calc_mod(counter - (long) multiplier * number);
                    int position = lowerBound(v[i], mod1 - w);
                    answer = (answer + (long) w * v[i].size() + sum[i] - (long) mod1 * (v[i].size() - position)) % mod2;
                }
                counter += total;
                return;
            }
            counter++;
            answer = (answer + calc_mod(counter - number)) % mod2;
        }
        int startDigit = (depth == 0) ? 1 : 0;
        for (int d = startDigit; d <= 9; d++) {
            process_numbers(depth + 1, number * 10 + d);
        }
    }

    static int lowerBound(List<Integer> list, int value) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= value) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Long.parseLong(br.readLine());
        generate_sequences(0, 0);
        for (int i = 0; i <= 6; i++) {
            Collections.sort(v[i]);
            long sum_i = 0;
            for (int val : v[i]) {
                sum_i += val;
            }
            sum[i] = sum_i % mod2;
        }
        total = counter;
        counter = 0;
        answer = 0;
        process_numbers(0, 0);
        System.out.println((answer + mod2) % mod2);
    }
}
